from pathlib import Path
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from xml.sax.saxutils import escape
root=Path(__file__).resolve().parents[1]
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='Lead',fontName='Helvetica',fontSize=12,leading=18,textColor=colors.HexColor('#334155'),spaceAfter=14))
styles['BodyText'].leading=15
styles['BodyText'].spaceAfter=9
styles['Heading1'].textColor=colors.HexColor('#155e75')
styles['Heading2'].textColor=colors.HexColor('#155e75')
story=[]
def p(text,style='BodyText'): story.append(Paragraph(text,styles[style]))
def gap(h=12): story.append(Spacer(1,h))
def table(rows,widths):
    cells=[[Paragraph(escape(str(x)),styles['BodyText']) for x in row] for row in rows]
    t=Table(cells,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e0f2fe')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#cbd5e1'))]))
    story.append(t)
def page():story.append(PageBreak())
p('PROJECT PYTHON / CLI / OTOMATISASI','Heading2');gap(35)
p('ScrapMCP','Title')
p('Pengumpulan dan Pengarsipan Materi<br/>melalui Terminal dan MCP Xiaozhi','Heading1');gap(20)
p('Laporan implementasi dan panduan demonstrasi', 'Lead')
p('Versi aplikasi 1.0.0 | 31 Oktober 2026','BodyText')
gap(20)
table([['Identitas kelompok','Diisi sebelum pengumpulan'],['Anggota 1 / NIM','........................................................'],['Anggota 2 / NIM','........................................................'],['Anggota 3 / NIM','........................................................'],['Mata kuliah / dosen / kelas','........................................................']],[180,320])
gap(22)
p('Status dokumen','Heading2')
p('Laporan ini mendeskripsikan implementasi yang disertakan, bukan klaim kontribusi individu. Lengkapi identitas, bukti pengujian Windows dan demonstrasi Xiaozhi asli sebelum pengumpulan. Mesin scraping diadaptasi dari repo pengguna dengan atribusi sumber yang disertakan.')
page()
p('01 / Masalah dan rancangan','Heading1')
p('Latar belakang','Heading2')
p('Materi pembelajaran tersebar pada artikel web, PDF, dan video dengan subtitle. Penyalinan, pembersihan teks, pencatatan sumber, penyusunan folder dan pencadangan manual membutuhkan langkah berulang. ScrapMCP menyatukan pekerjaan ini dalam aplikasi terminal yang dapat dijalankan sendiri.')
p('Tujuan','Heading2')
p('Mengambil materi publik, mengekstrak isi dan metadata, membersihkan teks menggunakan regex, menyimpan hasil terstruktur, mengelompokkan file, membuat laporan dan backup. Integrasi MCP memberi Xiaozhi akses ke operasi yang sama tanpa menggantikan CLI wajib.')
p('Rancangan proses','Heading2')
table([['Tahap','Hasil'],['Input','URL manual, daftar URL, topik riset, atau pemanggilan tool MCP'],['Pengambilan','requests + BeautifulSoup; PDF dan YouTube melalui parser khusus'],['Normalisasi','Pembersihan noise/spasi, email, validasi DOI'],['Penyimpanan','JSON hasil ekstraksi, JSON/Markdown bersih, dataset CSV/JSON'],['Organisasi','Folder kategori/tanggal dan identitas hash untuk duplikasi'],['Luaran','Rekap PDF/Markdown/JSON dan ZIP dengan manifest checksum']],[110,390])
gap(15)
p('Batas cakupan','Heading2')
p('Aplikasi tidak memerlukan web server, VPS, database eksternal atau ESP32 untuk mode manual. Tidak menyediakan OCR, browser headless lokal atau pengenalan suara sendiri. Suara dan pemilihan tool merupakan tanggung jawab layanan Xiaozhi. Riset memakai sumber eksternal dan kuis heuristik dari kode asal.')
page()
p('02 / Implementasi materi wajib','Heading1')
table([['Materi','Implementasi dan bukti'],['Ch. 9 Regex','engine.clean_record dan upstream_scraper: re.sub, re.findall, re.fullmatch; pembersihan berita, email dan DOI.'],['Ch. 10 Baca/tulis','storage: open, Path, json, csv; raw/processed dan pembacaan batch URL.'],['Ch. 11 Organisasi','storage: folder kategori/tanggal, nama aman Windows, ZipFile, MANIFEST SHA-256.'],['Ch. 12 CLI','cli: argparse, subcommands, --data-dir, --category dan menu interaktif.'],['Ch. 13 Scraping','network + upstream_scraper: requests.get dan BeautifulSoup, HTML/PDF/YouTube serta sumber akademik.']],[120,380])
gap(15)
p('Struktur kode','Heading2')
p('<b>cli.py</b> menerima input; <b>service.py</b> menyatukan alur; <b>engine.py</b> mengadaptasi scraper lengkap; <b>network.py</b> membatasi unduhan; <b>storage.py</b> mengarsipkan; <b>reports.py</b> membuat laporan; <b>mcp_server.py</b> menyediakan tools.')
p('Keandalan data','Heading2')
p('Penulisan atomik mengurangi risiko file setengah tertulis. File lock menyelaraskan penulisan antaraproses. Hash URL, konten dan kategori mencegah penyimpanan ulang hasil identik. Backup tidak mengikutkan backup lain; setiap file memiliki checksum. Kegagalan scraping dicatat tanpa menambahkan materi kosong.')
p('Sumber dan adaptasi','Heading2')
p('Mesin asli: github.com/Franklnir/xiaozhi-knowledge-base, file xiaozhi/services/scraper_service.py. Modul lengkap disertakan. Perubahan terbatas: hostname YouTube, status HTTP error, serta penghapusan retry riset rekursif. Packaging, dataset lokal, CLI dan integrasi mandiri ditambahkan. Detail SHA dan atribusi ada di SOURCE_ATTRIBUTION.md.')
page()
p('03 / Penggunaan dan integrasi','Heading1')
p('Instalasi Windows/Linux','Heading2')
p('Pasang Python 3.10+ dan pipx. Ekstrak proyek, masuk direktori berisi pyproject.toml, jalankan <b>pipx install .</b>, lalu <b>scrapmcp</b>. Setelah pipx ensurepath, terminal mungkin perlu dibuka ulang. Alternatif virtual environment dan installer .bat/.sh tersedia dalam README.')
p('Urutan demo dasar','Heading2')
for t in ['1. scrapmcp --help: tunjukkan opsi CLI.', '2. scrapmcp scrape URL --category informatika: ambil sumber publik.', '3. scrapmcp list dan scrapmcp read ID: tampilkan materi.', '4. scrapmcp export: buka dataset CSV/JSON.', '5. scrapmcp report: buka summary.pdf.', '6. scrapmcp backup: buka ZIP dan MANIFEST.json.']:
    p(t)
p('Demo offline','Heading2')
p('<b>scrapmcp demo</b> memproses fixture HTML buatan dan menghasilkan seluruh luaran. Dataset dilabeli simulation. Gunakan untuk latihan atau cadangan presentasi; tetap demonstrasikan scraping URL publik untuk menunjukkan Ch. 13 dalam kondisi jaringan nyata.')
p('MCP Xiaozhi','Heading2')
p('Pilih menu 2, tempel endpoint wss:// lengkap milik akun Xiaozhi pada prompt tersembunyi. Aplikasi membuka WebSocket keluar dan menyajikan tools melalui MCP SDK. Xiaozhi melakukan initialize, tools/list dan tools/call. Terminal harus tetap aktif.')
p('scrape_webpage langsung mengarsipkan URL yang diminta. research_topic hanya menghasilkan kandidat; confirm_and_save_research_material menyimpan setelah persetujuan dalam percakapan. Token tidak disimpan ke file. Mode stdio juga tersedia bagi klien MCP desktop.')
page()
p('04 / Pengujian, evaluasi, batasan','Heading1')
p('Pengujian terotomasi','Heading2')
p('19 tes lulus pada Python 3.12/Linux dalam lingkungan pembuatan. Tes mencakup fixture HTML, PDF sintetis, regex, CSV, duplikasi/penulisan bersamaan, laporan, manifest ZIP, blok URL/redirect privat, batas respons, serta dua sesi WebSocket MCP lokal.')
p('Tes MCP memakai transport WebSocket sungguhan dengan klien Xiaozhi simulasi: initialize, tools/list, tools/call, invalid arguments, penyimpanan materi, riset/konfirmasi, backup dan ping. Pengujian ini tidak menggunakan akun Xiaozhi pengguna.')
p('Batas verifikasi','Heading2')
p('Uji scraping langsung docs.python.org gagal pada resolusi DNS lingkungan ini; akses live sumber belum terverifikasi. Windows belum dijalankan langsung. Workflow GitHub Actions untuk Windows/Linux Python 3.10/3.12 disertakan untuk verifikasi lanjutan. Endpoint Xiaozhi asli tidak tersedia dalam pengujian ini.')
p('Risiko operasional','Heading2')
p('Website dapat memberi HTTP 403/429, mengubah struktur atau memerlukan JavaScript. YouTube bisa tidak menyediakan subtitle. PDF scan memerlukan OCR. Jina bersifat opt-in dan dapat membatasi layanan. Pemeriksaan IP/redirect bukan jaminan sandbox terhadap DNS rebinding. Koneksi MCP hanya diberikan kepada akun tepercaya.')
p('Tindak lanjut sebelum pengumpulan','Heading2')
for t in ['Lengkapi identitas dan pembagian kerja nyata setiap anggota.', 'Jalankan instalasi serta satu scraping live di komputer Windows/Linux kelompok.', 'Uji endpoint Xiaozhi asli, dokumentasikan hasil tanpa memperlihatkan token.', 'Rekam narasi kelompok, tampilkan dataset, kode wajib, PDF dan ZIP.', 'Pahami dan sebutkan bagian kode adaptasi; ikuti ketentuan dosen tentang penggunaan referensi.']:
    p('- '+t)
p('Referensi','Heading2')
p('Repo asal dan snapshot: SOURCE_ATTRIBUTION.md. Dokumentasi penggunaan: README.md. Hasil pemeriksaan: docs/TEST_RESULTS.md. Skenario video: docs/DEMO_DAN_PEMBAGIAN.md.')
def footer(c,doc):
    c.setStrokeColor(colors.HexColor('#cbd5e1')); c.line(45,38,550,38)
    c.setFont('Helvetica',8); c.setFillColor(colors.HexColor('#64748b'))
    c.drawString(45,25,'SCRAPMCP 1.0 | Laporan implementasi proyek Python')
    c.drawRightString(550,25,str(doc.page))
SimpleDocTemplate(str(root/'docs/LAPORAN_PROYEK.pdf'),pagesize=A4,leftMargin=45,rightMargin=45,topMargin=45,bottomMargin=55).build(story,onFirstPage=footer,onLaterPages=footer)
